import itertools, json, sys

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64

# Generate all candidate triples (a,b,c) with a<b and a+b=c
candidates = []
for a, b in itertools.combinations(L, 2):
    s = a + b
    if s in L:
        # Ensure distinctness (c is larger than both a and b as positive ints)
        if s != a and s != b:
            candidates.append((a, b, s))

# Exact cover search via simple backtracking (Algorithm X style)

# Map each element to the list of triples that contain it
elem_to_triples = {x: [] for x in L}
for idx, triple in enumerate(candidates):
    for x in triple:
        elem_to_triples[x].append(idx)

solution = []
used = set()

def backtrack():
    if len(used) == len(L):
        return True
    # Choose the element with fewest remaining triples (heuristic)
    remaining = [e for e in L if e not in used]
    # if any element has no possible triples left, backtrack
    min_elem = None
    min_options = None
    for e in remaining:
        options = [i for i in elem_to_triples[e] if not any(x in used for x in candidates[i])]
        if not options:
            return False
        if min_options is None or len(options) < len(min_options):
            min_options = options
            min_elem = e
    # Try each option
    for idx in min_options:
        triple = candidates[idx]
        # add triple
        solution.append(triple)
        for x in triple:
            used.add(x)
        if backtrack():
            return True
        # backtrack
        for x in triple:
            used.remove(x)
        solution.pop()
    return False

found = backtrack()
if not found:
    print(json.dumps({"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}))
else:
    # ensure exactly 15 triples (should be the case as 45 elements)
    result = {"triples": solution}
    print("WITNESS: " + json.dumps({"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": result}))

import json

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

def find_partition(numbers):
    nums = set(numbers)
    triples = []
    nlist = numbers
    for i, a in enumerate(nlist):
        for b in nlist[i+1:]:
            c = a + b
            if c in nums:
                triples.append((a, b, c))
    triples_by_num = {n: [] for n in numbers}
    for t in triples:
        a, b, c = t
        triples_by_num[a].append(t)
        triples_by_num[b].append(t)
        triples_by_num[c].append(t)
    def search(remaining):
        if not remaining:
            return []
        best_num = None
        best_cands = None
        for n in remaining:
            cands = [t for t in triples_by_num[n] if set(t).issubset(remaining)]
            if not cands:
                return None
            if best_cands is None or len(cands) < len(best_cands):
                best_num = n
                best_cands = cands
                if len(best_cands) == 1:
                    break
        for t in best_cands:
            new_rem = remaining - set(t)
            sol = search(new_rem)
            if sol is not None:
                return [t] + sol
        return None
    return search(nums)

solution = find_partition(L)
if solution is None:
    witness = {"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"search","search_exhausted":True}
else:
    solution_lists = [list(t) for t in solution]
    witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":{"triples":solution_lists}}
print("WITNESS: " + json.dumps(witness, separators=(',', ':')))
